/* =========================================================
   🛡️ v3.5.6: 글로벌 에러 핸들러 + ErrorBoundary
   - 미처리 Promise rejection → 무시 (crash 방지)
   - 렌더링 에러 → 복구 UI 표시 (white screen 방지)
   ========================================================= */

// 🛡️ 글로벌 미처리 Promise Rejection 핸들러
// React Native에서 unhandled rejection은 앱을 종료시킬 수 있음
if (global.ErrorUtils) {
  const originalHandler = global.ErrorUtils.getGlobalHandler();
  global.ErrorUtils.setGlobalHandler((error, isFatal) => {
    if (isFatal) {
      console.error("🔴 치명적 오류:", error?.message || error);
      // 치명적 오류는 기본 핸들러에 위임
      if (originalHandler) originalHandler(error, isFatal);
    } else {
      console.warn("🟡 비치명적 오류:", error?.message || error);
      // 비치명적 오류는 로그만 남기고 무시 (crash 방지)
    }
  });
}

// 🛡️ ErrorBoundary: 렌더링 중 발생하는 에러를 잡아 white screen 방지
class AppErrorBoundary extends Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, errorMsg: "" };
  }

  static getDerivedStateFromError(error) {
    return { hasError: true, errorMsg: error?.message || "알 수 없는 오류" };
  }

  componentDidCatch(error, errorInfo) {
    console.error("🔴 렌더링 크래시:", error?.message, errorInfo?.componentStack?.slice(0, 500));
  }

  render() {
    if (this.state.hasError) {
      return (
        <SafeAreaView style={{ flex: 1, justifyContent: "center", alignItems: "center", backgroundColor: "#0f172a", padding: 32 }}>
          <Text style={{ fontSize: 48, marginBottom: 16 }}>⚠️</Text>
          <Text style={{ fontSize: 20, fontWeight: "800", color: "#f8fafc", marginBottom: 12, textAlign: "center" }}>
            앱에 오류가 발생했습니다
          </Text>
          <Text style={{ fontSize: 14, color: "#94a3b8", marginBottom: 24, textAlign: "center", lineHeight: 22 }}>
            {this.state.errorMsg}
          </Text>
          <TouchableOpacity
            onPress={() => this.setState({ hasError: false, errorMsg: "" })}
            style={{
              backgroundColor: "#3b82f6",
              paddingHorizontal: 32,
              paddingVertical: 14,
              borderRadius: 12,
            }}
          >
            <Text style={{ color: "#fff", fontWeight: "700", fontSize: 16 }}>다시 시도</Text>
          </TouchableOpacity>
          <Text style={{ fontSize: 12, color: "#475569", marginTop: 16, textAlign: "center" }}>
            문제가 지속되면 앱을 재시작해주세요
          </Text>
        </SafeAreaView>
      );
    }
    return this.props.children;
  }
}

/* =========================================================
   📁 v3.5.15d: 슬롯 시스템 (다중 데이터셋 관리)
   - 최대 10개 독립 데이터셋 (슬롯 0~9)
   - 슬롯 0 = novel_tiers.db (기존 데이터 하위호환)
   - 슬롯 1~9 = novel_tiers_slotN.db (새 데이터셋)
   - 메타데이터는 JSON 파일로 별도 관리 (DB 독립)
   ========================================================= */
const SLOT_META_PATH = FileSystem.documentDirectory + "slot_meta.json";
const MAX_SLOTS = 10;

function getSlotDbFilename(slotId) {
  if (slotId === 0) return "novel_tiers.db"; // 하위호환
  return `novel_tiers_slot${slotId}.db`;
}

// 현재 활성 슬롯 ID (모듈 레벨 — openDb에서 참조)
let activeSlotId = 0;
// 🔧 슬롯 세대 카운터: setTimeout 기반 지연 쓰기가 슬롯 전환 후 잘못된 DB에 기록되는 것 방지
let _slotGeneration = 0;
/** setTimeout 내에서 슬롯 전환 여부를 확인하는 안전한 지연 쓰기 래퍼 */
function safeDefer(fn) {
  const gen = _slotGeneration;
  setTimeout(() => {
    if (_slotGeneration !== gen) return; // 슬롯이 전환됨 → 이전 슬롯 데이터 무시
    fn();
  }, 0);
}

async function loadSlotMeta() {
  try {
    const info = await FileSystem.getInfoAsync(SLOT_META_PATH);
    if (!info.exists) {
      // 최초 실행: 기본 슬롯 1개 생성
      const defaultMeta = {
        activeSlotId: 0,
        slots: [{ id: 0, name: "기본 데이터", createdAt: Date.now(), novelCount: 0, lastAccessed: Date.now() }],
      };
      await FileSystem.writeAsStringAsync(SLOT_META_PATH, JSON.stringify(defaultMeta));
      return defaultMeta;
    }
    const raw = await FileSystem.readAsStringAsync(SLOT_META_PATH);
    const meta = JSON.parse(raw);
    // 안전 검증
    if (!meta || !Array.isArray(meta.slots)) {
      throw new Error("Invalid slot meta");
    }
    return meta;
  } catch (e) {
    console.warn("슬롯 메타 로드 실패:", e);
    // 복구: 기본 슬롯 반환
    return {
      activeSlotId: 0,
      slots: [{ id: 0, name: "기본 데이터", createdAt: Date.now(), novelCount: 0, lastAccessed: Date.now() }],
    };
  }
}

async function saveSlotMeta(meta) {
  try {
    await FileSystem.writeAsStringAsync(SLOT_META_PATH, JSON.stringify(meta));
  } catch (e) {
    console.warn("슬롯 메타 저장 실패:", e);
  }
}

// 슬롯 생성 (이름 지정, 다음 빈 ID 자동 할당)
async function createSlot(name) {
  const meta = await loadSlotMeta();
  if (meta.slots.length >= MAX_SLOTS) {
    return { success: false, error: `최대 ${MAX_SLOTS}개 슬롯까지 생성 가능합니다.` };
  }
  // 사용 중인 ID 집합
  const usedIds = new Set(meta.slots.map(s => s.id));
  let newId = -1;
  for (let i = 0; i < MAX_SLOTS; i++) {
    if (!usedIds.has(i)) { newId = i; break; }
  }
  if (newId === -1) {
    return { success: false, error: "사용 가능한 슬롯 ID가 없습니다." };
  }
  
  const newSlot = {
    id: newId,
    name: name || `슬롯 ${newId + 1}`,
    createdAt: Date.now(),
    novelCount: 0,
    lastAccessed: 0,
  };
  meta.slots.push(newSlot);
  // ID 순 정렬
  meta.slots.sort((a, b) => a.id - b.id);
  await saveSlotMeta(meta);
  return { success: true, slot: newSlot };
}

// 슬롯 삭제 (활성 슬롯은 삭제 불가, DB 파일도 삭제)
async function deleteSlot(slotId) {
  if (slotId === activeSlotId) {
    return { success: false, error: "현재 사용 중인 슬롯은 삭제할 수 없습니다." };
  }
  const meta = await loadSlotMeta();
  const idx = meta.slots.findIndex(s => s.id === slotId);
  if (idx === -1) {
    return { success: false, error: "슬롯을 찾을 수 없습니다." };
  }
  
  // DB 파일 삭제
  const dbFilename = getSlotDbFilename(slotId);
  const dbPath = FileSystem.documentDirectory + "SQLite/" + dbFilename;
  try {
    const info = await FileSystem.getInfoAsync(dbPath);
    if (info.exists) {
      await FileSystem.deleteAsync(dbPath, { idempotent: true });
      // WAL/SHM 파일도 삭제
      try { await FileSystem.deleteAsync(dbPath + "-wal", { idempotent: true }); } catch {}
      try { await FileSystem.deleteAsync(dbPath + "-shm", { idempotent: true }); } catch {}
    }
  } catch (e) {
    console.warn("슬롯 DB 파일 삭제 실패:", e);
  }
  
  meta.slots.splice(idx, 1);
  await saveSlotMeta(meta);
  return { success: true };
}

// 슬롯 이름 변경
async function renameSlot(slotId, newName) {
  const meta = await loadSlotMeta();
  const slot = meta.slots.find(s => s.id === slotId);
  if (!slot) return { success: false, error: "슬롯을 찾을 수 없습니다." };
  slot.name = newName;
  await saveSlotMeta(meta);
  return { success: true };
}

// 슬롯 작품 수 업데이트
async function updateSlotNovelCount(slotId, count) {
  try {
    const meta = await loadSlotMeta();
    const slot = meta.slots.find(s => s.id === slotId);
    if (slot) {
      slot.novelCount = count;
      slot.lastAccessed = Date.now();
      await saveSlotMeta(meta);
    }
  } catch {}
}

// 모든 지연 쓰기 강제 flush (슬롯 전환 전 필수)
async function flushAllPendingWrites() {
  // 1. deferSetAppMeta 강제 flush
  if (_metaBatchTimer) {
    clearTimeout(_metaBatchTimer);
    _metaBatchTimer = null;
  }
  const metaSnapshot = { ..._pendingMetaWrites };
  for (const k of Object.keys(_pendingMetaWrites)) delete _pendingMetaWrites[k];
  if (Object.keys(metaSnapshot).length > 0) {
    try { await batchSetAppMeta(metaSnapshot); } catch (e) {
      console.warn("슬롯 전환 전 메타 flush 실패 — 재시도:", e);
      // 🔧 1회 재시도: DB 잠금 등 일시적 오류 대응
      try { await batchSetAppMeta(metaSnapshot); } catch (e2) {
        console.warn("슬롯 전환 전 메타 flush 재시도 실패:", e2);
      }
    }
  }
  
  // 2. choiceLogQueue 강제 flush
  try { await choiceLogQueue.flush(); } catch (e) {
    console.warn("슬롯 전환 전 choiceLog flush 실패:", e);
  }
  
  // 3. patternUpdate 강제 flush
  if (patternUpdateScheduled) {
    patternUpdateScheduled = false;
    const batch = patternUpdateBatch.splice(0);
    if (batch.length > 0) {
      try { await processPatternUpdates(batch); } catch (e) {
        console.warn("슬롯 전환 전 패턴 flush 실패:", e);
      }
    }
  }
  
  // 4. 매칭 큐 드레인 대기
  if (!isMatchQueueIdle()) {
    await waitForMatchQueueDrain(5000);
  }
}

// DB 레벨 슬롯 전환 (flush → close → open new)
async function switchSlotDb(newSlotId) {
  console.log(`[슬롯] 전환 시작: ${activeSlotId} → ${newSlotId}`);
  
  // 0. 🔧 슬롯 세대 증가 → 이전 슬롯의 setTimeout 기반 지연 쓰기를 무효화
  _slotGeneration++;

  // 1. 모든 지연 쓰기 flush
  await flushAllPendingWrites();

  // 2. 현재 슬롯 작품 수 업데이트
  try {
    const novels = await all("SELECT COUNT(*) as c FROM novels;");
    await updateSlotNovelCount(activeSlotId, novels?.[0]?.c || 0);
  } catch {}
  
  // 3. 현재 DB 연결 닫기
  await resetDbConnection();
  
  // 4. 활성 슬롯 변경
  activeSlotId = newSlotId;
  
  // 5. 슬롯 메타 업데이트
  const meta = await loadSlotMeta();
  meta.activeSlotId = newSlotId;
  const slot = meta.slots.find(s => s.id === newSlotId);
  if (slot) slot.lastAccessed = Date.now();
  await saveSlotMeta(meta);
  
  // 6. 캐시 전부 무효화
  invalidateMatchCache();
  invalidatePatternCache();
  invalidateWeightsCache();
  if (typeof genreMatchupCacheRef !== "undefined") {
    // genreMatchupCacheRef는 컴포넌트 스코프라 여기서 접근 불가 — 컴포넌트에서 처리
  }
  
  // 7. 새 DB 열기
  await openDb();
  
  console.log(`[슬롯] 전환 완료: 슬롯 ${newSlotId} (${getSlotDbFilename(newSlotId)})`);
}

/* =========================================================
   SQLite (Expo SDK 54 호환)
   ========================================================= */
let db = null;
let dbOpenPromise = null;
let dbLastSuccessTime = 0; // 마지막 성공 시간
let _dbOpenedForSlot = -1; // 🔧 현재 db가 어떤 슬롯용으로 열렸는지 추적

// 🔧 v3.4.7: 데이터베이스 초기화 (강화된 재연결 로직)
async function openDb() {
  // 🔧 슬롯 불일치 감지: 캐시된 연결이 다른 슬롯용이면 즉시 무효화
  // 원인: 앱 시작 시 pinned_tags/hidden_tags useEffect가 loadSlotMeta() 완료 전에
  //   openDb()를 호출하면 슬롯 0 DB로 연결이 캐시되어 이후 모든 쿼리가 잘못된 슬롯으로 감
  if (db && _dbOpenedForSlot !== activeSlotId) {
    console.warn(`[openDb] 슬롯 불일치: db=슬롯${_dbOpenedForSlot}, active=슬롯${activeSlotId} → 캐시 무효화`);
    try { await db.closeAsync(); } catch (_) {}
    db = null;
    dbOpenPromise = null;
    dbLastSuccessTime = 0;
  }

  // 이미 연결 시도 중이면 해당 Promise를 기다림
  if (dbOpenPromise) {
    try {
      return await dbOpenPromise;
    } catch (e) {
      dbOpenPromise = null;
      db = null;
    }
  }

  // 🔧 v3.5.3: 캐시 시간 단축 (5초→1초) + 테스트 실패 시 실제 close
  if (db && Date.now() - dbLastSuccessTime < 1000) {
    return db;
  }

  // 기존 연결이 있으면 테스트
  if (db) {
    try {
      // 간단한 쿼리로 연결 테스트
      await db.getAllAsync("SELECT 1;");
      dbLastSuccessTime = Date.now();
      return db;
    } catch (e) {
      // 연결이 죽었으면 실제로 닫고 정리
      console.warn("DB 연결 테스트 실패:", e.message);
      try { await db.closeAsync(); } catch (_) {}
      db = null;
    }
  }

  // 새 연결 생성
  // 🔧 v3.5.15d: 슬롯 시스템 — activeSlotId에 따른 DB 파일명
  const dbFilename = getSlotDbFilename(activeSlotId);
  dbOpenPromise = SQLite.openDatabaseAsync(dbFilename);
  
  try {
    db = await dbOpenPromise;
    _dbOpenedForSlot = activeSlotId; // 🔧 연결된 슬롯 기록
    // 🔧 v3.5.3: WAL 모드 + busy_timeout + synchronous 최적화
    // WAL: 쓰기 중에도 읽기 가능 (동시 접근 안정성 대폭 향상)
    // busy_timeout: DB 잠금 시 5초 대기 후 에러 (즉시 실패 방지)
    // synchronous=NORMAL: WAL에서 권장, 성능+안전성 균형
    try {
      await db.runAsync("PRAGMA journal_mode=WAL;");
      await db.runAsync("PRAGMA busy_timeout=5000;");
      await db.runAsync("PRAGMA synchronous=NORMAL;");
    } catch (pragmaErr) {
      console.warn("PRAGMA 설정 실패 (무시 가능):", pragmaErr.message);
    }
    dbLastSuccessTime = Date.now();
    console.log(`DB 연결 성공 (슬롯 ${activeSlotId}, ${dbFilename}, WAL mode)`);
    return db;
  } catch (e) {
    console.error("DB 열기 실패:", e.message);
    db = null;
    throw e;
  } finally {
    dbOpenPromise = null;
  }
}

// DB 연결 강제 리셋 (🔧 v3.5.3: 실제 close 수행)
async function resetDbConnection() {
  console.log("DB 연결 리셋");
  PerfMonitor.trackDbReconnect("resetDbConnection"); // 🔬
  const oldDb = db;
  db = null;
  dbOpenPromise = null;
  dbLastSuccessTime = 0;
  _dbOpenedForSlot = -1; // 🔧 슬롯 추적 리셋
  // 🔧 v3.5.3: 기존 연결을 실제로 닫아야 새 연결이 정상 작동
  if (oldDb) {
    try {
      await oldDb.closeAsync();
      console.log("기존 DB 연결 닫기 성공");
    } catch (closeErr) {
      console.warn("기존 DB 닫기 실패 (무시):", closeErr.message);
    }
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// 🔬 v3.5.9: 인앱 성능 진단 시스템 (Performance Monitor)
// - SQL 쿼리 추적 (횟수, 총 시간, 느린 쿼리 감지)
// - 주요 함수 실행 시간 측정
// - 에러/경고 로그 수집
// - 렌더 카운트 추적
// - 설정 탭 진단 대시보드에서 확인
// ═══════════════════════════════════════════════════════════════════════════
const PerfMonitor = {
  enabled: false,
  startTime: Date.now(),
  
  // SQL 통계
  sql: { totalCount: 0, totalTime: 0, slowCount: 0, errorCount: 0 },
  sqlLog: [],          // 최근 느린 쿼리 (>100ms) - 최대 30개
  SQL_SLOW_THRESHOLD: 100, // ms
  
  // 함수 실행 통계
  functions: {},       // { name: { count, totalTime, maxTime, lastTime, avgTime } }
  funcLog: [],         // 최근 느린 함수 호출 (>200ms) - 최대 30개
  FUNC_SLOW_THRESHOLD: 200, // ms
  
  // 🆕 v3.5.9b: 함수 서브스텝 타이밍 (loadList 내부 분해용)
  _activeSteps: {},    // { funcName: { startTime, steps: [{name, duration}], trigger } }
  subStepLog: [],      // 최근 서브스텝 기록 - 최대 20개
  
  // 에러 로그
  errors: [],          // 최대 50개
  warnings: [],        // 최대 50개
  
  // 렌더 카운트
  renders: {},         // { componentName: count }
  
  // 🆕 DB 연결 안정성
  db: { retryCount: 0, reconnectCount: 0, lastError: null, lastErrorTime: 0, consecutiveErrors: 0, maxConsecutiveErrors: 0 },
  dbEvents: [],        // 최대 30개 - 리트라이/재연결 이벤트
  
  // 🆕 화면 전환 추적
  navigation: [],      // 최대 30개 - { from, to, time }
  lastScreen: "home",
  
  // 🆕 이미지 로드 추적
  images: { loadCount: 0, errorCount: 0, cachedCount: 0 },
  imageErrors: [],     // 최대 20개
  
  // 🆕 앱 라이프사이클
  lifecycle: [],       // 최대 20개 - { event, time }
  backgroundCount: 0,
  foregroundCount: 0,
  _lastForegroundTime: 0, // 🆕 v3.5.9b: 마지막 포그라운드 전환 시각
  
  // 🆕 상태 크기 스냅샷 (주기적)
  stateSnapshots: [],  // 최대 10개
  
  // === SQL 추적 ===
  trackSQL(opName, sql, durationMs, error = null, rowCount = null) {
    if (!this.enabled) return;
    this.sql.totalCount++;
    this.sql.totalTime += durationMs;
    if (error) {
      this.sql.errorCount++;
      this.errors = [{ type: "SQL", op: opName, sql: sql?.substring(0, 80), error: String(error).substring(0, 120), time: Date.now(), duration: durationMs }, ...this.errors].slice(0, 50);
    }
    if (durationMs > this.SQL_SLOW_THRESHOLD) {
      this.sql.slowCount++;
      this.sqlLog = [{ op: opName, sql: sql?.substring(0, 100), duration: durationMs, time: Date.now(), rows: rowCount }, ...this.sqlLog].slice(0, 30);
    }
  },
  
  // === 함수 실행 추적 ===
  trackFunc(name, durationMs, trigger = null) {
    if (!this.enabled) return;
    if (!this.functions[name]) {
      this.functions[name] = { count: 0, totalTime: 0, maxTime: 0, lastTime: 0, minTime: Infinity };
    }
    const f = this.functions[name];
    f.count++;
    f.totalTime += durationMs;
    f.lastTime = durationMs;
    if (durationMs > f.maxTime) f.maxTime = durationMs;
    if (durationMs < f.minTime) f.minTime = durationMs;
    
    // 🆕 v3.5.9b: BG→FG 직후 호출 여부 판별 (3초 이내)
    const afterFG = this._lastForegroundTime > 0 && (Date.now() - this._lastForegroundTime) < 3000;
    
    if (durationMs > this.FUNC_SLOW_THRESHOLD) {
      this.funcLog = [{ name, duration: durationMs, time: Date.now(), trigger, afterFG }, ...this.funcLog].slice(0, 30);
    }
  },
  
  // 🆕 v3.5.9b: 서브스텝 타이밍 (loadList 내부 분해)
  beginFunc(funcName, trigger) {
    if (!this.enabled) return;
    this._activeSteps[funcName] = { startTime: Date.now(), steps: [], trigger: trigger || null };
  },
  stepFunc(funcName, stepName) {
    if (!this.enabled) return;
    const active = this._activeSteps[funcName];
    if (!active) return;
    const now = Date.now();
    const prev = active.steps.length > 0 ? active.steps[active.steps.length - 1] : null;
    const stepStart = prev ? prev._endTime : active.startTime;
    active.steps.push({ name: stepName, duration: now - stepStart, _endTime: now });
  },
  endFunc(funcName) {
    if (!this.enabled) return;
    const active = this._activeSteps[funcName];
    if (!active) return;
    const totalDuration = Date.now() - active.startTime;
    const afterFG = this._lastForegroundTime > 0 && (Date.now() - this._lastForegroundTime) < 3000;
    
    // 함수 통계 기록
    this.trackFunc(funcName, totalDuration, active.trigger);
    
    // 서브스텝 로그 (느린 호출만)
    if (totalDuration > this.FUNC_SLOW_THRESHOLD) {
      const steps = active.steps.map(s => ({ name: s.name, duration: s.duration }));
      this.subStepLog = [{ func: funcName, total: totalDuration, steps, trigger: active.trigger, afterFG, time: Date.now() }, ...this.subStepLog].slice(0, 20);
    }
    
    delete this._activeSteps[funcName];
  },
  
  // === 에러/경고 기록 ===
  logError(context, error) {
    if (!this.enabled) return;
    this.errors = [{ type: "Error", context, error: String(error).substring(0, 200), time: Date.now() }, ...this.errors].slice(0, 50);
  },
  logWarning(context, msg) {
    if (!this.enabled) return;
    this.warnings = [{ context, msg: String(msg).substring(0, 200), time: Date.now() }, ...this.warnings].slice(0, 50);
  },
  
  // === 렌더 추적 ===
  trackRender(componentName) {
    if (!this.enabled) return;
    this.renders[componentName] = (this.renders[componentName] || 0) + 1;
  },
  
  // === DB 안정성 추적 ===
  trackDbRetry(opName, attempt, errorMsg) {
    if (!this.enabled) return;
    this.db.retryCount++;
    this.db.consecutiveErrors++;
    if (this.db.consecutiveErrors > this.db.maxConsecutiveErrors) {
      this.db.maxConsecutiveErrors = this.db.consecutiveErrors;
    }
    this.db.lastError = errorMsg?.substring(0, 100);
    this.db.lastErrorTime = Date.now();
    this.dbEvents = [{ type: "retry", op: opName, attempt, error: errorMsg?.substring(0, 80), time: Date.now() }, ...this.dbEvents].slice(0, 30);
  },
  trackDbReconnect(reason) {
    if (!this.enabled) return;
    this.db.reconnectCount++;
    this.dbEvents = [{ type: "reconnect", reason: reason?.substring(0, 60), time: Date.now() }, ...this.dbEvents].slice(0, 30);
  },
  trackDbSuccess() {
    if (!this.enabled) return;
    this.db.consecutiveErrors = 0; // 성공 시 연속 에러 리셋
  },
  
  // === 화면 전환 추적 ===
  trackNavigation(from, to) {
    if (!this.enabled) return;
    this.navigation = [{ from, to, time: Date.now() }, ...this.navigation].slice(0, 30);
    this.lastScreen = to;
  },
  
  // === 이미지 로드 추적 ===
  trackImageLoad(success, uri) {
    if (!this.enabled) return;
    if (success) {
      this.images.loadCount++;
    } else {
      this.images.errorCount++;
      this.imageErrors = [{ uri: uri?.substring(0, 80), time: Date.now() }, ...this.imageErrors].slice(0, 20);
    }
  },
  
  // === 라이프사이클 추적 ===
  trackLifecycle(event) {
    if (!this.enabled) return;
    this.lifecycle = [{ event, time: Date.now() }, ...this.lifecycle].slice(0, 20);
    if (event === "background") this.backgroundCount++;
    if (event === "foreground") {
      this.foregroundCount++;
      this._lastForegroundTime = Date.now(); // 🆕 v3.5.9b
    }
  },
  
  // === 상태 크기 스냅샷 ===
  snapshotState(sizes) {
    if (!this.enabled) return;
    this.stateSnapshots = [{ ...sizes, time: Date.now() }, ...this.stateSnapshots].slice(0, 10);
  },
  
  // === 전체 리셋 ===
  reset() {
    this.sql = { totalCount: 0, totalTime: 0, slowCount: 0, errorCount: 0 };
    this.sqlLog = [];
    this.functions = {};
    this.funcLog = [];
    this._activeSteps = {};
    this.subStepLog = [];
    this.errors = [];
    this.warnings = [];
    this.renders = {};
    this.db = { retryCount: 0, reconnectCount: 0, lastError: null, lastErrorTime: 0, consecutiveErrors: 0, maxConsecutiveErrors: 0 };
    this.dbEvents = [];
    this.navigation = [];
    this.images = { loadCount: 0, errorCount: 0, cachedCount: 0 };
    this.imageErrors = [];
    this.lifecycle = [];
    this.backgroundCount = 0;
    this.foregroundCount = 0;
    this._lastForegroundTime = 0;
    this.stateSnapshots = [];
    this.startTime = Date.now();
  },
  
  // === 요약 스냅샷 생성 ===
  getSummary() {
    const uptime = Date.now() - this.startTime;
    const funcEntries = Object.entries(this.functions)
      .map(([name, s]) => ({ name, ...s, avgTime: s.count > 0 ? Math.round(s.totalTime / s.count) : 0 }))
      .sort((a, b) => b.totalTime - a.totalTime);
    
    return {
      uptime,
      sql: { ...this.sql, avgTime: this.sql.totalCount > 0 ? Math.round(this.sql.totalTime / this.sql.totalCount) : 0 },
      sqlLog: [...this.sqlLog],
      functions: funcEntries,
      funcLog: [...this.funcLog],
      errors: [...this.errors],
      warnings: [...this.warnings],
      renders: Object.entries(this.renders).sort((a, b) => b[1] - a[1]).map(([name, count]) => ({ name, count })),
      totalErrors: this.errors.length,
      totalWarnings: this.warnings.length,
      // 🆕 DB 안정성
      db: { ...this.db },
      dbEvents: [...this.dbEvents],
      // 🆕 화면 전환
      navigation: [...this.navigation],
      // 🆕 이미지
      images: { ...this.images },
      imageErrors: [...this.imageErrors],
      // 🆕 라이프사이클
      lifecycle: [...this.lifecycle],
      backgroundCount: this.backgroundCount,
      foregroundCount: this.foregroundCount,
      // 🆕 상태 크기
      stateSnapshots: [...this.stateSnapshots],
      // 🆕 v3.5.9b: 서브스텝 타이밍
      subStepLog: [...this.subStepLog],
    };
  },
};

// 🔬 비동기 함수 래핑 헬퍼 — 실행 시간 자동 측정
function perfWrap(name, fn) {
  return async function(...args) {
    if (!PerfMonitor.enabled) return fn.apply(this, args);
    const t0 = Date.now();
    try {
      const result = await fn.apply(this, args);
      PerfMonitor.trackFunc(name, Date.now() - t0);
      return result;
    } catch (e) {
      PerfMonitor.trackFunc(name, Date.now() - t0);
      PerfMonitor.logError(name, e);
      throw e;
    }
  };
}

// 🔧 v3.4.7: 안전한 DB 실행 래퍼 (자동 재연결 + 더 적극적인 재시도)
async function safeDbOperation(operation, operationName = "DB") {
  const maxRetries = 5;
  
  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      // 매 시도마다 연결 확인
      const database = await openDb();
      if (!database) {
        throw new Error("Database is null after openDb");
      }
      
      const result = await operation(database);
      dbLastSuccessTime = Date.now();
      PerfMonitor.trackDbSuccess(); // 🔬
      return result;
    } catch (e) {
      const errorMsg = e.message || "";
      
      // 🔧 v3.5.15c: 경합 오류와 연결 오류를 분리
      // BUSY/LOCKED는 WAL 모드에서 정상적인 경합 — resetDbConnection 금지
      // resetDbConnection은 다른 동시 작업의 DB 연결도 파괴하여 연쇄 크래시 유발
      const isContentionError = 
        errorMsg.includes("locked") ||
        errorMsg.includes("busy") ||
        errorMsg.includes("SQLITE_BUSY") ||
        errorMsg.includes("SQLITE_LOCKED");
      
      const isConnectionError = !isContentionError && (
        errorMsg.includes("NullPointerException") ||
        errorMsg.includes("prepareAsync") ||
        errorMsg.includes("rejected") ||
        errorMsg.includes("database") ||
        errorMsg.includes("null") ||
        errorMsg.includes("closed") ||
        errorMsg.includes("disk I/O") ||
        errorMsg.includes("no such table")
      );
      
      console.warn(`${operationName} 오류 (시도 ${attempt + 1}/${maxRetries}):`, errorMsg,
        isContentionError ? "[경합-대기]" : isConnectionError ? "[연결-리셋]" : "[기타]");
      PerfMonitor.trackDbRetry(operationName, attempt + 1, errorMsg); // 🔬
      
      // 🔧 v3.5.15c: 연결 오류만 resetDbConnection (경합 오류는 대기만)
      // 경합: busy_timeout=5000 내에서 자동 재시도, 그래도 실패 시 직접 retry
      // 연결: DB가 죽었거나 null이므로 리셋 필요
      if (isConnectionError) {
        await resetDbConnection();
      } else if (!isContentionError && attempt > 1) {
        // 기타 오류: 3번째 시도부터 리셋 (보수적)
        await resetDbConnection();
      }
      // 경합 오류: resetDbConnection 절대 하지 않음 (대기 후 재시도만)
      
      if (attempt === maxRetries - 1) {
        throw e;
      }
      
      // 🔧 v3.5.15c: 경합은 짧은 랜덤 대기 (jitter), 연결은 긴 대기
      const isNullPtr = errorMsg.includes("NullPointerException");
      let delay;
      if (isContentionError) {
        // 경합: 100~300ms 랜덤 대기 (thundering herd 방지)
        delay = 100 + Math.random() * 200 + attempt * 100;
      } else if (isNullPtr) {
        delay = 800 * (attempt + 1);
      } else {
        delay = 300 * (attempt + 1);
      }
      await new Promise(r => setTimeout(r, delay));
    }
  }
}

/** 단일 쿼리 실행 — 🔬 v3.5.9: 성능 추적 */
async function exec(sql, params = []) {
  const t0 = PerfMonitor.enabled ? Date.now() : 0;
  try {
    const result = await safeDbOperation(
      (database) => database.runAsync(sql, params),
      "exec"
    );
    if (PerfMonitor.enabled) PerfMonitor.trackSQL("exec", sql, Date.now() - t0);
    return result;
  } catch (e) {
    if (PerfMonitor.enabled) PerfMonitor.trackSQL("exec", sql, Date.now() - t0, e);
    throw e;
  }
}

/** SELECT 전체 — 🔬 v3.5.9: 성능 추적 */
async function all(sql, params = []) {
  const t0 = PerfMonitor.enabled ? Date.now() : 0;
  try {
    const result = await safeDbOperation(
      (database) => database.getAllAsync(sql, params),
      "all"
    );
    // 🔬 v3.5.9b: row count 추가
    if (PerfMonitor.enabled) PerfMonitor.trackSQL("all", sql, Date.now() - t0, null, Array.isArray(result) ? result.length : null);
    return result;
  } catch (e) {
    if (PerfMonitor.enabled) PerfMonitor.trackSQL("all", sql, Date.now() - t0, e);
    throw e;
  }
}

/** SELECT 첫 번째 — 🔬 v3.5.9: 성능 추적 */
async function first(sql, params = []) {
  const t0 = PerfMonitor.enabled ? Date.now() : 0;
  try {
    const result = await safeDbOperation(
      (database) => database.getFirstAsync(sql, params),
      "first"
    );
    if (PerfMonitor.enabled) PerfMonitor.trackSQL("first", sql, Date.now() - t0);
    return result;
  } catch (e) {
    if (PerfMonitor.enabled) PerfMonitor.trackSQL("first", sql, Date.now() - t0, e);
    throw e;
  }
}

/** 트랜잭션 실행 (🔧 v3.5.3: 대량 배치 청크 처리) */
async function execBatch(queries) {
  if (!queries || queries.length === 0) return;
  
  // 🔧 v3.5.3: 50개 이상이면 청크로 분할 (트랜잭션 타임아웃 방지)
  const CHUNK_SIZE = 50;
  if (queries.length > CHUNK_SIZE) {
    for (let i = 0; i < queries.length; i += CHUNK_SIZE) {
      const chunk = queries.slice(i, i + CHUNK_SIZE);
      await safeDbOperation(
        async (database) => {
          await database.withTransactionAsync(async () => {
            for (const { sql, params } of chunk) {
              await database.runAsync(sql, params || []);
            }
          });
        },
        `execBatch[${i}~${Math.min(i + CHUNK_SIZE, queries.length)}]`
      );
      // 청크 사이 DB 안정화 대기
      if (i + CHUNK_SIZE < queries.length) {
        await new Promise(r => setTimeout(r, 50));
      }
    }
    return;
  }
  
  return safeDbOperation(
    async (database) => {
      await database.withTransactionAsync(async () => {
        for (const { sql, params } of queries) {
          await database.runAsync(sql, params || []);
        }
      });
    },
    "execBatch"
  );
}

/* =========================================================
   🔄 매칭 큐잉 시스템 (v3.4.6)
   - 빠른 연타에도 DB 트랜잭션 충돌 방지
   - UI는 즉시 응답, DB는 순차 처리
   - pending 매치 추적으로 중복 방지
   ========================================================= */
const matchQueue = [];
let isProcessingMatchQueue = false;
let matchQueueUpdateCallback = null; // 상태 업데이트용 콜백
const pendingMatchPairs = new Set(); // 큐에서 처리 대기 중인 pair 키들

// 큐 상태 업데이트 콜백 등록
function setMatchQueueCallback(callback) {
  matchQueueUpdateCallback = callback;
}

// 큐 상태 알림
function notifyQueueStatus() {
  if (matchQueueUpdateCallback) {
    matchQueueUpdateCallback({
      pending: matchQueue.length,
      processing: isProcessingMatchQueue
    });
  }
}

// pair 키 생성 헬퍼 (중복 체크용)
function matchPairKey(aId, bId) {
  return aId < bId ? `${aId}|${bId}` : `${bId}|${aId}`;
}

// 매치가 이미 큐에 있는지 확인
function isMatchPending(aId, bId) {
  return pendingMatchPairs.has(matchPairKey(aId, bId));
}

// 🔧 v3.5.14: 매칭 큐가 비어있는지 확인 (자동매칭 큐 드레인 대기용)
function isMatchQueueIdle() {
  return matchQueue.length === 0 && !isProcessingMatchQueue;
}

// 🔧 v3.5.14: 매칭 큐 드레인 대기 (최대 timeout ms)
function waitForMatchQueueDrain(timeout = 2000) {
  return new Promise((resolve) => {
    if (isMatchQueueIdle()) { resolve(true); return; }
    const start = Date.now();
    const check = () => {
      if (isMatchQueueIdle() || (Date.now() - start) > timeout) {
        resolve(isMatchQueueIdle());
        return;
      }
      setTimeout(check, 50);
    };
    check();
  });
}

// 매칭 작업을 큐에 추가 (pairKey도 함께 추적)
function enqueueMatchTask(task, pairKey = null) {
  return new Promise((resolve, reject) => {
    // 중복 방지: 이미 큐에 있으면 무시
    if (pairKey && pendingMatchPairs.has(pairKey)) {
      console.log("매치 큐: 이미 대기 중인 조합, 무시:", pairKey);
      resolve(null);
      return;
    }
    
    if (pairKey) {
      pendingMatchPairs.add(pairKey);
    }
    
    matchQueue.push({ task, resolve, reject, pairKey });
    notifyQueueStatus();
    processMatchQueue();
  });
}

// 큐 순차 처리
async function processMatchQueue() {
  if (isProcessingMatchQueue) return;
  isProcessingMatchQueue = true;
  notifyQueueStatus();
  
  while (matchQueue.length > 0) {
    const { task, resolve, reject, pairKey } = matchQueue.shift();
    notifyQueueStatus();
    
    try {
      const result = await task();
      resolve(result);
    } catch (e) {
      console.warn("매칭 큐 처리 오류:", e.message);
      // 🔧 v3.5.15c: resetDbConnection 제거
      // 이유: safeDbOperation이 내부적으로 연결 오류를 구분하여 처리함
      // 여기서 resetDbConnection을 호출하면 동시 실행 중인 다른 DB 작업
      // (분석, choiceLog flush, deferSetAppMeta 등)의 연결도 함께 파괴됨
      // → 연쇄 크래시의 근본 원인이었음
      reject(e);
    } finally {
      // 처리 완료 후 pending에서 제거
      if (pairKey) {
        pendingMatchPairs.delete(pairKey);
      }
    }
    
    // 각 작업 사이에 약간의 딜레이 (DB 안정성)
    await new Promise(r => setTimeout(r, 50));
  }
  
  isProcessingMatchQueue = false;
  notifyQueueStatus();
}

/* =========================================================
   🔧 v3.5.15: 매칭 캐시 시스템
   - pickRandomUnseenPair의 SELECT * FROM novels + SELECT FROM matches 반복 제거
   - 매칭 1회당 2개 중쿼리 → 캐시 히트 시 0개
   - 캐시 무효화: loadList 완료, 작품 추가/삭제, 매칭 화면 진입 시
   ========================================================= */
const matchCache = {
  novels: null,         // normalizeNovel'd 배열
  playedSet: null,      // Set<pairKey>
  novelsTs: 0,          // novels 캐시 타임스탬프
  matchesTs: 0,         // matches 캐시 타임스탬프
  dirty: true,          // 무효화 플래그
  TTL: 15000,           // 15초 유효기간
};

function invalidateMatchCache() {
  matchCache.dirty = true;
}

// 캐시에서 played set에 새 매치 추가 (DB 재조회 불필요)
function addToMatchCachePlayed(aId, bId) {
  if (matchCache.playedSet) {
    const key = aId < bId ? `${aId}|${bId}` : `${bId}|${aId}`;
    matchCache.playedSet.add(key);
  }
}

// 캐시된 novels 목록에서 특정 작품의 rating/wins/losses 등을 업데이트
function updateMatchCacheNovel(id, updates) {
  if (!matchCache.novels) return;
  const idx = matchCache.novels.findIndex(n => n.id === id);
  if (idx >= 0) {
    matchCache.novels[idx] = { ...matchCache.novels[idx], ...updates };
  }
}

async function getMatchCacheData(forceRefresh = false) {
  const now = Date.now();
  const novelsStale = !matchCache.novels || matchCache.dirty || (now - matchCache.novelsTs > matchCache.TTL);
  const matchesStale = !matchCache.playedSet || matchCache.dirty || (now - matchCache.matchesTs > matchCache.TTL);
  
  if (!novelsStale && !matchesStale && !forceRefresh) {
    return { novels: matchCache.novels, playedSet: matchCache.playedSet };
  }
  
  // 갱신 필요
  if (novelsStale || forceRefresh) {
    const rawNovels = await all("SELECT * FROM novels ORDER BY rating DESC;");
    matchCache.novels = (rawNovels || []).map(normalizeNovel);
    matchCache.novelsTs = now;
  }
  
  if (matchesStale || forceRefresh) {
    const matchRows = await all("SELECT a_id,b_id FROM matches;");
    const newSet = new Set(
      (matchRows || []).map((r) => {
        const a = r.a_id, b = r.b_id;
        return a < b ? `${a}|${b}` : `${b}|${a}`;
      })
    );
    // 🔧 v3.5.15b: 기존 played에 있지만 아직 DB 미기록인 엔트리 보존
    // (decide에서 addToMatchCachePlayed 후 enqueueMatchTask INSERT 전 경합 방지)
    if (matchCache.playedSet) {
      for (const key of matchCache.playedSet) newSet.add(key);
    }
    matchCache.playedSet = newSet;
    matchCache.matchesTs = now;
  }
  
  matchCache.dirty = false;
  return { novels: matchCache.novels, playedSet: matchCache.playedSet };
}

/* -------------------- Migration -------------------- */
async function columnExists(table, name) {
  const rows = await all(`PRAGMA table_info(${table});`);
  return (rows || []).some((r) => r.name === name);
}

async function ensureColumn(table, name, type, defaultExpr) {
  const exists = await columnExists(table, name);
  if (!exists) {
    await exec(
      `ALTER TABLE ${table} ADD COLUMN ${name} ${type}${
        defaultExpr ? " DEFAULT " + defaultExpr : ""
      };`
    );
  }
}

// 🔧 v3.4.6: 타임스탬프 + 카운터로 중복 방지 강화
let uuidCounter = 0;
function uuid() {
  const timestamp = Date.now().toString(36);
  const counter = (uuidCounter++ % 1000).toString(36).padStart(3, '0');
  const random = "xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0,
      v = c === "x" ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
  return `${timestamp}${counter}-${random}`;
}

async function initDb() {
  // DB 연결 확보
  const database = await openDb();
  
  // 테이블 생성 (한 번에 하나씩)
  await database.runAsync(`CREATE TABLE IF NOT EXISTS novels (
    id TEXT PRIMARY KEY NOT NULL,
    title TEXT UNIQUE NOT NULL,
    author TEXT,
    tags TEXT,
    platforms TEXT,
    note TEXT,
    read_count INTEGER,
    rating REAL,
    rd REAL,
    wins INTEGER,
    losses INTEGER,
    match_count INTEGER,
    tier TEXT,
    created_at INTEGER
  );`);
  
  await database.runAsync(`CREATE TABLE IF NOT EXISTS matches (
    id TEXT PRIMARY KEY NOT NULL,
    a_id TEXT NOT NULL,
    b_id TEXT NOT NULL,
    winner_id TEXT,
    decided_by TEXT,
    gap_when_matched REAL,
    k_factor_used REAL,
    created_at INTEGER
  );`);

  // 🚀 v2.8.1: 마이그레이션 최적화 - PRAGMA 한 번만 호출
  const existingColumns = await all(`PRAGMA table_info(novels);`);
  const existingNames = new Set((existingColumns || []).map(r => r.name));
  
  const migrations = [
    ["author", "TEXT", "''"],
    ["tags", "TEXT", "''"],
    ["platforms", "TEXT", "''"],
    ["note", "TEXT", "''"],
    ["read_count", "INTEGER", "0"],
    ["rating", "REAL", "1500"],
    ["rd", "REAL", "350"],
    ["wins", "INTEGER", "0"],
    ["losses", "INTEGER", "0"],
    ["match_count", "INTEGER", "0"],
    ["tier", "TEXT", "'C'"],
    ["created_at", "INTEGER", String(Date.now())],
    ["awards", "TEXT", "''"],
    ["total_episodes", "INTEGER", "0"],
    ["status", "TEXT", "'reading'"],
    ["pinned", "INTEGER", "0"],
    ["cover_image", "TEXT", "''"],
    ["link", "TEXT", "''"],
    ["work_status", "TEXT", "'ongoing'"],
    ["read_count_updated_at", "INTEGER", "1737072000000"],
    ["major_genre", "TEXT", "''"],
    ["sub_genre", "TEXT", "''"],
    ["gaiden_status", "TEXT", "'none'"],
    ["gaiden_read_count", "INTEGER", "0"],
    ["gaiden_total_episodes", "INTEGER", "0"],
    ["manual_tier", "TEXT", "NULL"],
    ["reread_count", "INTEGER", "1"], // 📚 v3.0.4: 다회독 카운트 (기본 1회)
    // 🏷️ v5.0 태그 시스템
    ["tag_data", "TEXT", "''"],      // JSON: [{tag, intensity}, ...]
    ["aliases", "TEXT", "''"],        // JSON: ["하늑", ...] 작품 별명
    // 💬 v3.2.2: 인상깊은 문장
    ["memorable_quote", "TEXT", "''"], // 작품에서 인상깊었던 문장
  ];
  
  // 필요한 마이그레이션만 실행
  for (const [name, type, defaultExpr] of migrations) {
    if (!existingNames.has(name)) {
      await database.runAsync(
        `ALTER TABLE novels ADD COLUMN ${name} ${type}${defaultExpr ? " DEFAULT " + defaultExpr : ""};`
      );
    }
  }

  // 🗂 이주의 추천/기타 메타데이터 저장용
  await database.runAsync(`CREATE TABLE IF NOT EXISTS app_meta (
    key   TEXT PRIMARY KEY NOT NULL,
    value TEXT
  );`);
  
  // 📋 v3.3.0: 예정 작품 테이블 (가등록 - 본 목록에 포함되지 않음)
  await database.runAsync(`CREATE TABLE IF NOT EXISTS planned_novels (
    id TEXT PRIMARY KEY NOT NULL,
    title TEXT UNIQUE NOT NULL,
    author TEXT,
    tags TEXT,
    platforms TEXT,
    note TEXT,
    total_episodes INTEGER,
    cover_image TEXT,
    link TEXT,
    work_status TEXT,
    major_genre TEXT,
    sub_genre TEXT,
    priority INTEGER,
    created_at INTEGER
  );`);
  
  // 🆕 v3.4: planned_novels 필드 확장 (홈탭 수준으로)
  await ensureColumn("planned_novels", "expected_rating", "REAL", "1500");
  await ensureColumn("planned_novels", "expected_tier", "TEXT", "''");
  await ensureColumn("planned_novels", "interest_level", "INTEGER", "3");
  await ensureColumn("planned_novels", "discovery_source", "TEXT", "''");
  await ensureColumn("planned_novels", "first_chapter_read", "INTEGER", "0");
  await ensureColumn("planned_novels", "scheduled_start_date", "INTEGER", "0");
  await ensureColumn("planned_novels", "similar_novels", "TEXT", "''");
  await ensureColumn("planned_novels", "why_interested", "TEXT", "''");
  await ensureColumn("planned_novels", "tag_data", "TEXT", "''");
  
  // 🖼️ v3.4.5: 표지 라이브러리 테이블
  await database.runAsync(`CREATE TABLE IF NOT EXISTS cover_library (
    id TEXT PRIMARY KEY NOT NULL,
    file_path TEXT NOT NULL,
    status TEXT DEFAULT 'unused',
    novel_id TEXT,
    original_name TEXT,
    width INTEGER,
    height INTEGER,
    file_size INTEGER,
    created_at INTEGER
  );`);
  await database.runAsync(`CREATE INDEX IF NOT EXISTS idx_cover_status ON cover_library(status);`);
  await database.runAsync(`CREATE INDEX IF NOT EXISTS idx_cover_novel ON cover_library(novel_id);`);
  
  // 🆕 성능 최적화: 인덱스 추가
  await database.runAsync(`CREATE INDEX IF NOT EXISTS idx_novels_rating ON novels(rating DESC);`);
  await database.runAsync(`CREATE INDEX IF NOT EXISTS idx_novels_created ON novels(created_at DESC);`);
  await database.runAsync(`CREATE INDEX IF NOT EXISTS idx_novels_pinned ON novels(pinned DESC);`);
  await database.runAsync(`CREATE INDEX IF NOT EXISTS idx_novels_status ON novels(status);`);
  await database.runAsync(`CREATE INDEX IF NOT EXISTS idx_novels_title ON novels(title COLLATE NOCASE);`);
  await database.runAsync(`CREATE INDEX IF NOT EXISTS idx_matches_created ON matches(created_at ASC);`);
  
  // ═══════════════════════════════════════════════════════════════════════════════
  // 🧠 취향 발견 시스템 v3.5.0 - Preference Discovery System
  // ═══════════════════════════════════════════════════════════════════════════════
  
  // 1️⃣ choice_logs: 선택 기록 + 맥락 스냅샷 + 이상 탐지
  await database.runAsync(`CREATE TABLE IF NOT EXISTS choice_logs (
    id TEXT PRIMARY KEY NOT NULL,
    match_id TEXT NOT NULL,
    
    -- 선택 결과
    winner_id TEXT NOT NULL,
    loser_id TEXT NOT NULL,
    
    -- 예측 정보
    predicted_winner_id TEXT,
    prediction_confidence REAL,
    prediction_factors TEXT,
    was_correct INTEGER,
    
    -- 스냅샷 (JSON)
    winner_snapshot TEXT,
    loser_snapshot TEXT,
    comparison TEXT,
    
    -- 이상 탐지
    anomaly_score REAL DEFAULT 0,
    anomaly_factors TEXT,
    
    -- 메타
    match_type TEXT DEFAULT 'user',
    session_position INTEGER,
    created_at INTEGER NOT NULL
  );`);
  await database.runAsync(`CREATE INDEX IF NOT EXISTS idx_cl_created ON choice_logs(created_at DESC);`);
  await database.runAsync(`CREATE INDEX IF NOT EXISTS idx_cl_type ON choice_logs(match_type);`);
  await database.runAsync(`CREATE INDEX IF NOT EXISTS idx_cl_winner ON choice_logs(winner_id);`);
  await database.runAsync(`CREATE INDEX IF NOT EXISTS idx_cl_anomaly ON choice_logs(anomaly_score DESC);`);
  
  // 2️⃣ preference_patterns: 발견된 취향 패턴 (정적+동적 통합)
  await database.runAsync(`CREATE TABLE IF NOT EXISTS preference_patterns (
    id TEXT PRIMARY KEY NOT NULL,
    
    -- 패턴 정의
    category TEXT NOT NULL,
    pattern_key TEXT NOT NULL,
    
    -- 동적 통계 (선택 행동)
    sample_size INTEGER DEFAULT 0,
    win_count INTEGER DEFAULT 0,
    win_rate REAL,
    
    -- 신뢰 구간 (윌슨)
    confidence_lower REAL,
    confidence_upper REAL,
    significance REAL,
    
    -- 정적 분석 연계
    static_metric TEXT,
    static_value REAL,
    static_deviation REAL,
    
    -- 상세 정보 (JSON)
    details TEXT,
    
    -- 인사이트 상태
    is_notable INTEGER DEFAULT 0,
    insight_level TEXT,
    insight_title TEXT,
    insight_description TEXT,
    
    is_shown INTEGER DEFAULT 0,
    shown_at INTEGER,
    user_reaction TEXT,
    user_confirmed INTEGER DEFAULT 0,
    
    -- 시간
    first_seen_at INTEGER NOT NULL,
    last_updated_at INTEGER NOT NULL
  );`);
  await database.runAsync(`CREATE INDEX IF NOT EXISTS idx_pp_category ON preference_patterns(category);`);
  await database.runAsync(`CREATE INDEX IF NOT EXISTS idx_pp_notable ON preference_patterns(is_notable DESC, significance DESC);`);
  await database.runAsync(`CREATE INDEX IF NOT EXISTS idx_pp_key ON preference_patterns(pattern_key);`);
  await database.runAsync(`CREATE UNIQUE INDEX IF NOT EXISTS idx_pp_unique ON preference_patterns(category, pattern_key);`);
  
  // 3️⃣ insight_queue: 인사이트 대기열 + 사용자 응답
  await database.runAsync(`CREATE TABLE IF NOT EXISTS insight_queue (
    id TEXT PRIMARY KEY NOT NULL,
    
    -- 출처
    source TEXT NOT NULL,
    pattern_id TEXT,
    
    -- 인사이트 내용
    insight_type TEXT NOT NULL,
    priority INTEGER DEFAULT 50,
    confidence REAL DEFAULT 0,
    
    title TEXT NOT NULL,
    description TEXT NOT NULL,
    evidence TEXT,
    content TEXT,
    
    -- 상태
    status TEXT DEFAULT 'pending',
    shown_at INTEGER,
    user_response TEXT,
    responded_at INTEGER,
    
    created_at INTEGER NOT NULL
  );`);
  await database.runAsync(`CREATE INDEX IF NOT EXISTS idx_iq_status ON insight_queue(status, priority DESC);`);
  // 🔧 DB 최적화: preference_patterns 복합 인덱스 (loadPreferencePatterns 248ms → ~50ms)
  await database.runAsync(`CREATE INDEX IF NOT EXISTS idx_pp_sample_conf ON preference_patterns(sample_size, confidence_lower);`);
  // 🔧 DB 최적화: insight_queue 정렬 커버링 인덱스
  await database.runAsync(`CREATE INDEX IF NOT EXISTS idx_iq_status_sort ON insight_queue(status, priority DESC, created_at DESC);`);
  
  // 4️⃣ weight_config: 예측 가중치 버전 관리
  await database.runAsync(`CREATE TABLE IF NOT EXISTS weight_config (
    version INTEGER PRIMARY KEY AUTOINCREMENT,
    
    -- 기본 가중치
    w_elo REAL DEFAULT 0.35,
    w_h2h REAL DEFAULT 0.20,
    w_overall_winrate REAL DEFAULT 0.10,
    w_reliability REAL DEFAULT 0.05,
    
    -- 취향 기반 가중치
    w_genre_matchup REAL DEFAULT 0.10,
    w_tag_power REAL DEFAULT 0.10,
    w_read_preference REAL DEFAULT 0.05,
    w_author_affinity REAL DEFAULT 0.03,
    w_coordinate_zone REAL DEFAULT 0.02,
    
    -- 변경 정보
    change_source TEXT,
    change_reason TEXT,
    changed_weights TEXT,
    
    -- 성능 추적
    accuracy_at_creation REAL,
    accuracy_current REAL,
    sample_size_for_accuracy INTEGER,
    
    -- 상태
    is_active INTEGER DEFAULT 0,
    created_at INTEGER NOT NULL
  );`);
  
  // 기본 가중치 버전이 없으면 생성
  const activeWeight = await database.getFirstAsync(
    `SELECT version FROM weight_config WHERE is_active = 1`
  );
  if (!activeWeight) {
    await database.runAsync(
      `INSERT INTO weight_config (is_active, created_at) VALUES (1, ?)`,
      [Date.now()]
    );
  }
  
  // 🧠 v3.5.0 Phase 2: preference_patterns 마이그레이션
  await ensureColumn("preference_patterns", "user_confirmed", "INTEGER", "0");
  
  // 🧠 v3.5.0 Phase 2: insight_queue 마이그레이션
  await ensureColumn("insight_queue", "confidence", "REAL", "0");
  await ensureColumn("insight_queue", "content", "TEXT", "''");
  await ensureColumn("insight_queue", "responded_at", "INTEGER", "0");
}

// -----------------------------------------
// app_meta 헬퍼 (키-값 JSON 저장)
// -----------------------------------------
async function getAppMeta(key) {
  try {
    const row = await first("SELECT value FROM app_meta WHERE key=?", [key]);
    if (!row || row.value == null) return null;
    try {
      return JSON.parse(row.value);
    } catch {
      return null;
    }
  } catch (e) {
    console.warn("getAppMeta 오류:", e);
    return null;
  }
}

async function setAppMeta(key, value) {
  try {
    const json = JSON.stringify(value ?? null);
    // 🔧 v3.5.9: UPSERT 패턴 (DELETE+INSERT 2쿼리 → 1쿼리, WAL 경합 해소)
    await exec("INSERT OR REPLACE INTO app_meta (key,value) VALUES (?,?);", [key, json]);
  } catch (e) {
    console.warn("setAppMeta 오류:", e);
  }
}

// 🔧 v3.5.11 성능: 여러 setAppMeta를 1트랜잭션에 묶어 실행 (fsync 1회)
// 🔧 v3.5.15c: 수동 BEGIN/COMMIT → execBatch(withTransactionAsync)로 교체
//   문제: 개별 exec("BEGIN")→exec("INSERT")→exec("COMMIT")은 각각 safeDbOperation을
//   거치므로, 중간에 resetDbConnection이 발생하면 트랜잭션 상태가 유실됨 → 연쇄 크래시
//   해결: execBatch는 withTransactionAsync로 단일 safeDbOperation 내에서 원자적 실행
async function batchSetAppMeta(entries) {
  if (!entries || typeof entries !== "object") return;
  const keys = Object.keys(entries);
  if (keys.length === 0) return;
  if (keys.length === 1) {
    await setAppMeta(keys[0], entries[keys[0]]);
    return;
  }
  try {
    const queries = keys.map(key => ({
      sql: "INSERT OR REPLACE INTO app_meta (key,value) VALUES (?,?)",
      params: [key, JSON.stringify(entries[key] ?? null)],
    }));
    await execBatch(queries);
  } catch (e) {
    console.warn("batchSetAppMeta 오류:", e);
  }
}

// 🔧 v3.5.15d: 지연 쓰기 코어레싱 — 큐 처리 중 동시 DB 쓰기 방지
// 기존 50ms → 300ms 윈도우: 큐 작업 내 deferSetAppMeta 호출이 작업 완료 후 flush되도록
// 큐 처리 중이면 추가 대기 (매칭 큐 DB 쓰기와 경합 방지)
const _pendingMetaWrites = {};
let _metaBatchTimer = null;

function deferSetAppMeta(key, value) {
  _pendingMetaWrites[key] = value;
  if (_metaBatchTimer) return; // 이미 타이머 대기 중
  _metaBatchTimer = setTimeout(async () => {
    // 🔧 v3.5.15d: 매칭 큐가 처리 중이면 드레인 대기 후 flush
    // 큐 작업의 execBatch와 이 flush의 execBatch가 동시 실행되면 SQLITE_BUSY 경합
    if (!isMatchQueueIdle()) {
      try {
        await waitForMatchQueueDrain(3000);
      } catch {}
    }
    // 🔧 스냅샷 후에 타이머 클리어 (drain 중 재진입 방지)
    const snapshot = { ..._pendingMetaWrites };
    for (const k of Object.keys(_pendingMetaWrites)) delete _pendingMetaWrites[k];
    _metaBatchTimer = null;
    try {
      await batchSetAppMeta(snapshot);
    } catch (e) {
      console.warn("deferSetAppMeta flush 오류:", e);
    }
  }, 300);
}

// ═══════════════════════════════════════════════════════════════
// 🔄 태그 시스템 v5.0 마이그레이션
// ═══════════════════════════════════════════════════════════════

/**
 * 태그 시스템 마이그레이션 실행
 * - Phase 1: tag_data가 비어있는 작품들에 대해 tags → tag_data 변환
 * - Phase 2: 작품 식별자를 aliases로 분리
 */
async function migrateTagSystem() {
  try {
    const version = await getAppMeta("tag_system_version") || 0;
    
    if (version < 1) {
      console.log("태그 시스템 v5.0 마이그레이션 Phase 1 시작...");
      
      // Phase 1: tags → tag_data 변환
      const novels = await all(
        "SELECT id, tags, tag_data FROM novels WHERE tag_data = '' OR tag_data IS NULL"
      );
      
      for (const novel of (novels || [])) {
        if (novel.tags) {
          const tagData = tagsStringToTagData(novel.tags, 3);
          await exec(
            "UPDATE novels SET tag_data = ? WHERE id = ?",
            [JSON.stringify(tagData), novel.id]
          );
        }
      }
      
      await setAppMeta("tag_system_version", 1);
      console.log(`태그 시스템 Phase 1 완료: ${(novels || []).length}개 작품 변환`);
    }
    
    if (version < 2) {
      console.log("태그 시스템 v5.0 마이그레이션 Phase 2 시작...");
      
      // Phase 2: 작품 식별자를 aliases로 분리
      const novels = await all("SELECT id, tag_data, aliases FROM novels");
      let migratedCount = 0;
      
      for (const novel of (novels || [])) {
        const tagData = parseTagData(novel.tag_data);
        const existingAliases = parseNovelAliases(novel.aliases);
        
        const newAliases = [...existingAliases];
        const cleanedTagData = [];
        let changed = false;
        
        for (const t of tagData) {
          if (isWorkIdentifier(t.tag)) {
            if (!newAliases.includes(t.tag)) {
              newAliases.push(t.tag);
              changed = true;
            }
          } else {
            cleanedTagData.push(t);
          }
        }
        
        if (changed) {
          await exec(
            "UPDATE novels SET tag_data = ?, aliases = ? WHERE id = ?",
            [JSON.stringify(cleanedTagData), JSON.stringify(newAliases), novel.id]
          );
          migratedCount++;
        }
      }
      
      await setAppMeta("tag_system_version", 2);
      console.log(`태그 시스템 Phase 2 완료: ${migratedCount}개 작품 업데이트`);
    }
    
    // 🔧 v3.4.5 Phase 3: major_genre/sub_genre를 tags에 병합 (일관성 보장)
    if (version < 3) {
      console.log("태그 시스템 v3.4.5 마이그레이션 Phase 3 시작 (태그 동기화)...");
      
      const novels = await all("SELECT id, tags, major_genre, sub_genre FROM novels");
      let syncedCount = 0;
      
      for (const novel of (novels || [])) {
        // 현재 tags 파싱
        const currentTags = (novel.tags || "")
          .split(",")
          .map(t => t.trim())
          .filter(Boolean);
        
        // major_genre, sub_genre 파싱
        let majorGenres = [];
        let subGenres = [];
        try {
          if (novel.major_genre) {
            const parsed = JSON.parse(novel.major_genre);
            majorGenres = Array.isArray(parsed) ? parsed : [parsed];
          }
        } catch {}
        try {
          if (novel.sub_genre) {
            const parsed = JSON.parse(novel.sub_genre);
            subGenres = Array.isArray(parsed) ? parsed : [parsed];
          }
        } catch {}
        
        // 누락된 장르를 tags에 추가
        const tagsSet = new Set(currentTags.map(t => t.toLowerCase()));
        const missingTags = [];
        
        for (const g of majorGenres) {
          if (g && !tagsSet.has(g.toLowerCase())) {
            missingTags.push(g);
          }
        }
        for (const g of subGenres) {
          if (g && !tagsSet.has(g.toLowerCase())) {
            missingTags.push(g);
          }
        }
        
        if (missingTags.length > 0) {
          const newTags = [...missingTags, ...currentTags].join(", ");
          await exec(
            "UPDATE novels SET tags = ? WHERE id = ?",
            [newTags, novel.id]
          );
          syncedCount++;
        }
      }
      
      // 예정 작품도 동기화
      const plannedNovels = await all("SELECT id, tags, major_genre, sub_genre FROM planned_novels");
      let plannedSyncedCount = 0;
      
      for (const novel of (plannedNovels || [])) {
        const currentTags = (novel.tags || "")
          .split(",")
          .map(t => t.trim())
          .filter(Boolean);
        
        let majorGenres = [];
        let subGenres = [];
        try {
          if (novel.major_genre) {
            const parsed = JSON.parse(novel.major_genre);
            majorGenres = Array.isArray(parsed) ? parsed : [parsed];
          }
        } catch {}
        try {
          if (novel.sub_genre) {
            const parsed = JSON.parse(novel.sub_genre);
            subGenres = Array.isArray(parsed) ? parsed : [parsed];
          }
        } catch {}
        
        const tagsSet = new Set(currentTags.map(t => t.toLowerCase()));
        const missingTags = [];
        
        for (const g of majorGenres) {
          if (g && !tagsSet.has(g.toLowerCase())) {
            missingTags.push(g);
          }
        }
        for (const g of subGenres) {
          if (g && !tagsSet.has(g.toLowerCase())) {
            missingTags.push(g);
          }
        }
        
        if (missingTags.length > 0) {
          const newTags = [...missingTags, ...currentTags].join(", ");
          await exec(
            "UPDATE planned_novels SET tags = ? WHERE id = ?",
            [newTags, novel.id]
          );
          plannedSyncedCount++;
        }
      }
      
      await setAppMeta("tag_system_version", 3);
      console.log(`태그 시스템 Phase 3 완료: 본 목록 ${syncedCount}개, 예정 목록 ${plannedSyncedCount}개 동기화`);
    }

    // ═══════════════════════════════════════════════════════════
    // Phase 4: 대장르 통합 + 유사 태그 정리 (v3.5.16)
    // - 호러→공포/스릴러, 현대물→현대, 시대물→사극, 노로맨스→노맨스
    // - novels, planned_novels, preference_patterns 일괄 치환
    // ═══════════════════════════════════════════════════════════
    if (version < 4) {
      const TAG_RENAMES = {
        "호러": "공포/스릴러",
        "현대물": "현대",
        "시대물": "사극",
        "노로맨스": "노맨스",
      };

      // 테이블별 태그 필드 치환 헬퍼
      async function migrateTagRenamesInTable(tableName) {
        const rows = await all(`SELECT id, tags, tag_data, major_genre, sub_genre FROM ${tableName}`);
        if (!rows || rows.length === 0) return 0;

        const updates = [];
        for (const row of rows) {
          let changed = false;
          let { tags, tag_data, major_genre, sub_genre } = row;

          for (const [oldName, newName] of Object.entries(TAG_RENAMES)) {
            // tags 문자열: 쉼표 구분 배열에서 정확한 태그만 치환
            if (tags && tags.includes(oldName)) {
              const tagArr = tags.split(",").map(t => t.trim());
              const replaced = tagArr.map(t => isSameTag(t, oldName) ? newName : t);
              const newStr = replaced.join(", ");
              if (newStr !== tags) { tags = newStr; changed = true; }
            }
            // tag_data JSON 배열
            if (tag_data) {
              try {
                const parsed = JSON.parse(tag_data);
                if (Array.isArray(parsed)) {
                  let tdChanged = false;
                  for (const td of parsed) {
                    if (isSameTag(td.tag, oldName)) { td.tag = newName; tdChanged = true; }
                  }
                  if (tdChanged) { tag_data = JSON.stringify(parsed); changed = true; }
                }
              } catch {}
            }
            // major_genre JSON 배열
            if (major_genre) {
              try {
                const arr = JSON.parse(major_genre);
                if (Array.isArray(arr)) {
                  let mgChanged = false;
                  const newArr = arr.map(g => {
                    if (isSameTag(g, oldName)) { mgChanged = true; return newName; }
                    return g;
                  });
                  if (mgChanged) { major_genre = JSON.stringify(newArr); changed = true; }
                }
              } catch {}
            }
            // sub_genre JSON 배열
            if (sub_genre) {
              try {
                const arr = JSON.parse(sub_genre);
                if (Array.isArray(arr)) {
                  let sgChanged = false;
                  const newArr = arr.map(g => {
                    if (isSameTag(g, oldName)) { sgChanged = true; return newName; }
                    return g;
                  });
                  if (sgChanged) { sub_genre = JSON.stringify(newArr); changed = true; }
                }
              } catch {}
            }
          }

          if (changed) {
            updates.push({
              sql: `UPDATE ${tableName} SET tags=?, tag_data=?, major_genre=?, sub_genre=? WHERE id=?`,
              params: [tags, tag_data, major_genre, sub_genre, row.id]
            });
          }
        }

        if (updates.length > 0) {
          for (let i = 0; i < updates.length; i += 50) {
            await execBatch(updates.slice(i, i + 50));
          }
        }
        return updates.length;
      }

      const novelFixed = await migrateTagRenamesInTable("novels");
      const plannedFixed = await migrateTagRenamesInTable("planned_novels");

      // preference_patterns: pattern_key 치환 (tag_power, genre_affinity 먼저 → genre_matchup 나중에)
      for (const [oldName, newName] of Object.entries(TAG_RENAMES)) {
        // tag_power: "tag:호러" → "tag:공포/스릴러"
        await exec(
          `UPDATE preference_patterns SET pattern_key = REPLACE(pattern_key, ?, ?) WHERE category = 'tag_power' AND pattern_key LIKE ?`,
          [`tag:${oldName}`, `tag:${newName}`, `%tag:${oldName}%`]
        );
        // genre_affinity: "genre:호러" → "genre:공포/스릴러"
        await exec(
          `UPDATE preference_patterns SET pattern_key = REPLACE(pattern_key, ?, ?) WHERE category = 'genre_affinity' AND pattern_key LIKE ?`,
          [`genre:${oldName}`, `genre:${newName}`, `%genre:${oldName}%`]
        );
        // genre_matchup: "판타지_vs_호러" → "판타지_vs_공포/스릴러" (가장 마지막)
        await exec(
          `UPDATE preference_patterns SET pattern_key = REPLACE(pattern_key, ?, ?) WHERE category = 'genre_matchup' AND pattern_key LIKE ?`,
          [oldName, newName, `%${oldName}%`]
        );
      }

      await setAppMeta("tag_system_version", 4);
      console.log(`태그 시스템 Phase 4 완료: 본 목록 ${novelFixed}개, 예정 목록 ${plannedFixed}개 태그 통합`);
    }

    return true;
  } catch (e) {
    console.warn("태그 시스템 마이그레이션 오류:", e);
    return false;
  }
}

/**
 * 단일 작품의 태그 동기화
 * tag_data를 마스터로, tags를 자동 갱신
 */

// ═══════════════════════════════════════════════════════════════
// 🔧 v3.5.8: 데이터 무결성 검증 및 자동 수정
// ═══════════════════════════════════════════════════════════════
// tags 문자열을 Single Source of Truth로 취급하여 파생 필드를 재계산
// 결정론적 복구만 수행 (원본 데이터 손상 위험 없음)
//
// 검증 항목:
// 1. tag_data ↔ tags 동기화 (tags에 없는 tag_data 항목 제거)
// 2. major_genre/sub_genre ↔ tags 동기화 (tags에서 재계산)
// 3. JSON 필드 파싱 검증 (깨진 JSON → 빈값 초기화)
// 4. 숫자 필드 NaN/null 정규화 (기본값 적용)
// 5. 고아 매치 정리 (삭제된 작품 참조 매치 제거)
// 6. cover_library 상태 검증 (used/unused 실제 참조 기준 재계산)
// ═══════════════════════════════════════════════════════════════

async function verifyDataIntegrity(options = {}) {
  const { silent = false, forceRun = false } = options;
  const INTEGRITY_VERSION = 1; // 버전 올리면 자동 재실행
  
  try {
    if (!forceRun) {
      const currentVersion = Number(await getAppMeta("integrity_check_version")) || 0;
      if (currentVersion >= INTEGRITY_VERSION) {
        return { skipped: true, message: "이미 최신 무결성 검증 완료" };
      }
    }
    
    const log = { fixed: 0, details: [] };
    const addLog = (category, msg) => {
      log.details.push(`[${category}] ${msg}`);
      if (!silent) console.log(`[무결성] ${category}: ${msg}`);
    };
    
    // ─── 1. novels 전체 로드 ───
    const novels = await all(
      "SELECT id, title, tags, tag_data, major_genre, sub_genre, " +
      "rating, rd, wins, losses, match_count, read_count, reread_count, " +
      "awards, platforms, aliases, cover_image FROM novels"
    );
    
    const novelIds = new Set((novels || []).map(n => n.id));
    const queries = [];
    let _integrityTagAttrs = null; // 1d에서 lazy 로드
    
    for (const novel of (novels || [])) {
      const fixes = {};
      let needsUpdate = false;
      
      // ── 1a. JSON 필드 파싱 검증 ──
      const jsonFields = [
        ["major_genre", ""],
        ["sub_genre", ""],
        ["tag_data", ""],
        ["awards", ""],
        ["platforms", "[]"],
        ["aliases", ""],
      ];
      for (const [field, fallback] of jsonFields) {
        const val = novel[field];
        if (val && val !== "") {
          try { JSON.parse(val); } catch {
            fixes[field] = fallback;
            needsUpdate = true;
            addLog("JSON수정", `${novel.title}: ${field} 파싱 실패 → 초기화`);
          }
        }
      }
      
      // ── 1b. 숫자 필드 NaN/null 정규화 ──
      const numFields = [
        ["rating", 1500], ["rd", 350],
        ["wins", 0], ["losses", 0], ["match_count", 0],
        ["read_count", 0], ["reread_count", 1],
      ];
      for (const [field, defaultVal] of numFields) {
        const val = novel[field];
        if (val === null || val === undefined || isNaN(Number(val))) {
          fixes[field] = defaultVal;
          needsUpdate = true;
          addLog("숫자수정", `${novel.title}: ${field}=${val} → ${defaultVal}`);
        }
      }
      
      // ── 1c. tags → tag_data 동기화 (삭제된 태그의 tag_data 잔존 제거) ──
      const currentTags = (novel.tags || "").split(",").map(t => t.trim()).filter(Boolean);
      const currentTagsLc = new Set(currentTags.map(t => t.toLowerCase()));
      
      const tagDataStr = fixes.tag_data !== undefined ? fixes.tag_data : (novel.tag_data || "");
      if (tagDataStr) {
        try {
          const parsed = JSON.parse(tagDataStr);
          if (Array.isArray(parsed)) {
            const filtered = parsed.filter(td => currentTagsLc.has((td.tag || "").toLowerCase()));
            if (filtered.length !== parsed.length) {
              const removed = parsed.length - filtered.length;
              fixes.tag_data = filtered.length > 0 ? JSON.stringify(filtered) : "";
              needsUpdate = true;
              addLog("태그동기", `${novel.title}: tag_data에서 고아 항목 ${removed}개 제거`);
            }
          }
        } catch {} // JSON 파싱 실패는 1a에서 이미 처리
      }
      
      // ── 1d. tags → major_genre/sub_genre 재계산 ──
      // 🔧 tagAttributes를 DB에서 로드하여 사용자 커스텀 장르 반영
      if (!_integrityTagAttrs) {
        try {
          const raw = await getAppMeta("tag_attributes");
          _integrityTagAttrs = safeParseJSON(raw, {});
        } catch { _integrityTagAttrs = {}; }
      }
      const allMajor = getAllMajorTags(_integrityTagAttrs);
      const allSub = getAllSubTags(_integrityTagAttrs);
      
      const detectedMajor = currentTags
        .filter(tag => allMajor.some(m => m.toLowerCase() === tag.toLowerCase()))
        .map(tag => allMajor.find(m => m.toLowerCase() === tag.toLowerCase()) || tag);
      const detectedSub = currentTags
        .filter(tag => allSub.some(s => s.toLowerCase() === tag.toLowerCase()))
        .map(tag => allSub.find(s => s.toLowerCase() === tag.toLowerCase()) || tag);
      
      const expectedMajor = detectedMajor.length > 0 ? JSON.stringify(detectedMajor) : "";
      const expectedSub = detectedSub.length > 0 ? JSON.stringify(detectedSub) : "";
      
      // JSON 수정 대상이 아닌 경우에만 비교 (1a에서 이미 초기화된 경우 스킵)
      if (fixes.major_genre === undefined) {
        const currentMajor = novel.major_genre || "";
        // 실제 내용 비교 (JSON 포맷 차이 무시)
        try {
          const curParsed = currentMajor ? JSON.stringify(JSON.parse(currentMajor)) : "";
          if (curParsed !== expectedMajor) {
            fixes.major_genre = expectedMajor;
            needsUpdate = true;
            addLog("장르동기", `${novel.title}: major_genre 불일치 → 재계산`);
          }
        } catch {
          fixes.major_genre = expectedMajor;
          needsUpdate = true;
        }
      }
      if (fixes.sub_genre === undefined) {
        const currentSub = novel.sub_genre || "";
        try {
          const curParsed = currentSub ? JSON.stringify(JSON.parse(currentSub)) : "";
          if (curParsed !== expectedSub) {
            fixes.sub_genre = expectedSub;
            needsUpdate = true;
            addLog("장르동기", `${novel.title}: sub_genre 불일치 → 재계산`);
          }
        } catch {
          fixes.sub_genre = expectedSub;
          needsUpdate = true;
        }
      }
      
      // ── 수정 쿼리 생성 ──
      if (needsUpdate) {
        const setClauses = [];
        const params = [];
        for (const [field, value] of Object.entries(fixes)) {
          setClauses.push(`${field}=?`);
          params.push(value);
        }
        params.push(novel.id);
        queries.push({
          sql: `UPDATE novels SET ${setClauses.join(", ")} WHERE id=?`,
          params,
        });
        log.fixed++;
      }
    }
    
    // ─── 2. 고아 매치 정리 (삭제된 작품 참조) ───
    const orphanMatches = await all(
      "SELECT id, a_id, b_id FROM matches WHERE a_id NOT IN (SELECT id FROM novels) OR b_id NOT IN (SELECT id FROM novels)"
    );
    if (orphanMatches && orphanMatches.length > 0) {
      for (const m of orphanMatches) {
        queries.push({
          sql: "DELETE FROM matches WHERE id=?",
          params: [m.id],
        });
      }
      addLog("고아매치", `삭제된 작품 참조 매치 ${orphanMatches.length}건 정리`);
    }
    
    // ─── 3. cover_library 상태 검증 ───
    const covers = await all("SELECT id, file_path, status, novel_id FROM cover_library");
    const plannedNovelsForCover = await all("SELECT id, cover_image FROM planned_novels WHERE cover_image IS NOT NULL AND cover_image != ''");
    const novelCovers = new Set((novels || []).filter(n => n.cover_image).map(n => n.cover_image));
    // 예정작 표지도 "사용 중"으로 취급
    for (const pn of (plannedNovelsForCover || [])) {
      if (pn.cover_image) novelCovers.add(pn.cover_image);
    }
    
    for (const cover of (covers || [])) {
      const isActuallyUsed = novelCovers.has(cover.file_path);
      const markedUsed = cover.status === "used";
      
      if (isActuallyUsed && !markedUsed) {
        // 실제 사용 중인데 unused로 표시된 경우
        const usingNovel = (novels || []).find(n => n.cover_image === cover.file_path);
        queries.push({
          sql: "UPDATE cover_library SET status='used', novel_id=? WHERE id=?",
          params: [usingNovel?.id || null, cover.id],
        });
        addLog("표지동기", `${cover.file_path}: unused → used 수정`);
      } else if (!isActuallyUsed && markedUsed) {
        // 실제 미사용인데 used로 표시된 경우
        queries.push({
          sql: "UPDATE cover_library SET status='unused', novel_id=NULL WHERE id=?",
          params: [cover.id],
        });
        addLog("표지동기", `${cover.file_path}: used → unused 수정`);
      }
    }
    
    // ─── 4. 고아 choice_logs 정리 ───
    const orphanLogs = await all(
      "SELECT id FROM choice_logs WHERE winner_id NOT IN (SELECT id FROM novels) OR loser_id NOT IN (SELECT id FROM novels)"
    );
    if (orphanLogs && orphanLogs.length > 0) {
      for (const cl of orphanLogs) {
        queries.push({
          sql: "DELETE FROM choice_logs WHERE id=?",
          params: [cl.id],
        });
      }
      addLog("고아로그", `삭제된 작품 참조 choice_log ${orphanLogs.length}건 정리`);
    }
    
    // ─── 실행 ───
    if (queries.length > 0) {
      await execBatch(queries);
      addLog("완료", `총 ${queries.length}건 쿼리 실행, ${log.fixed}개 작품 수정`);
    } else {
      addLog("완료", "불일치 없음 — 데이터 정합성 양호");
    }
    
    // 버전 기록 (자동 실행 시)
    if (!forceRun) {
      await setAppMeta("integrity_check_version", INTEGRITY_VERSION);
    }
    
    return {
      skipped: false,
      queriesExecuted: queries.length,
      novelsFixed: log.fixed,
      orphanMatchesRemoved: orphanMatches?.length || 0,
      details: log.details,
    };
  } catch (e) {
    console.warn("데이터 무결성 검증 오류:", e);
    return { error: e.message };
  }
}
async function syncNovelTags(novelId, tagData) {
  const tagsString = tagDataToString(tagData);
  await exec(
    "UPDATE novels SET tags = ?, tag_data = ? WHERE id = ?",
    [tagsString, JSON.stringify(tagData), novelId]
  );
}

/* =========================================================================
 * 🧠 취향 발견 시스템 (Preference Discovery System) v3.5.0
 * =========================================================================
 *
 * 목표: "아는 나 + 모르는 나"를 모두 찾아주는 AI 취향 분석 시스템
 *
 * ┌─────────────────────────────────────────────────────────────────────┐
 * │ 아키텍처                                                            │
 * │                                                                     │
 * │  ┌─────────────┐  ┌─────────────┐  ┌─────────────┐                │
 * │  │   수집층    │→ │   분석층    │→ │   발견층    │                │
 * │  │  Collector  │  │  Analyzer   │  │  Discoverer │                │
 * │  └─────────────┘  └─────────────┘  └─────────────┘                │
 * │         ↓                ↓                ↓                        │
 * │  ┌─────────────┐  ┌─────────────┐  ┌─────────────┐                │
 * │  │ choice_logs │  │  patterns   │  │  insights   │                │
 * │  └─────────────┘  └─────────────┘  └─────────────┘                │
 * └─────────────────────────────────────────────────────────────────────┘
 *
 * 패턴 카테고리 (12개):
 * - 동적: genre_matchup, genre_affinity, tag_power, tag_combo, tag_aversion,
 *         author_loyalty, rating_behavior, read_preference
 * - 정적: static_genre_rating, static_tag_droprate, static_spectrum, static_author
 *
 * 인사이트 유형:
 * - 확인형: CORE_PREFERENCE, GENRE_STRENGTH, TAG_AFFINITY, AUTHOR_LOYALTY
 * - 발견형: HIDDEN_PATTERN, CROSS_MISMATCH, RATING_OVERRIDE, UNCONSCIOUS_BIAS
 * - 질문형: ANOMALY_QUESTION, PREFERENCE_CHECK
 * ========================================================================= */

// ═══════════════════════════════════════════════════════════════════════════════
// 🔧 헬퍼 함수들
