// ═══════════════════════════════════════════════════════════════
// 🔧 조합식 태그 관리
// ═══════════════════════════════════════════════════════════════

// 조합식 태그 파싱 (예: "먼치킨+히로인" → {trait: "먼치킨", target: "히로인"})
function parseComboTag(tag) {
  if (!tag || !tag.includes("+")) return null;
  const parts = tag.split("+");
  if (parts.length !== 2) return null;
  return { trait: parts[0].trim(), target: parts[1].trim() };
}

// 조합식 태그 생성
function createComboTag(trait, target) {
  if (!trait || !target) return null;
  return `${trait}+${target}`;
}

// 중복 태그 제거 (대소문자 무시, 공백 제거)
function deduplicateTags(tags) {
  const seen = new Set();
  const result = [];
  for (const tag of tags) {
    const normalized = tag.trim().toLowerCase();
    if (!seen.has(normalized) && tag.trim()) {
      seen.add(normalized);
      result.push(tag.trim());
    }
  }
  return result;
}

// 🔧 v3.5.14: 쉼표 구분 태그 문자열 내 중복 제거
// "판타지, 먼치킨, 판타지" → "판타지, 먼치킨"
function deduplicateTagString(tagStr) {
  if (!tagStr) return tagStr;
  const arr = tagStr.split(",").map(t => t.trim()).filter(Boolean);
  return deduplicateTags(arr).join(", ");
}

/**
 * 🔧 v3.5.15b: 기존 DB 작품의 중복 태그 일괄 정리
 * - tags (쉼표 구분), tag_data (JSON 배열), major_genre (JSON), sub_genre (JSON) 모두 처리
 * - isSameTag 기반으로 공백/alias 변형 중복까지 제거
 * - 첫 번째 등장 태그만 유지 (원본 표기 보존)
 * @returns {{ fixed: number, total: number }} 수정된 작품 수
 */
async function deduplicateExistingNovelTags() {
  try {
    const novels = await all("SELECT id, tags, tag_data, major_genre, sub_genre FROM novels;");
    if (!novels || novels.length === 0) return { fixed: 0, total: 0 };
    
    const updates = [];
    
    for (const n of novels) {
      let changed = false;
      
      // 1. tags (쉼표 구분 문자열) 중복 제거
      let newTagsStr = n.tags || "";
      if (n.tags) {
        const tagArr = n.tags.split(",").map(t => t.trim()).filter(Boolean);
        const seen = [];
        const deduped = [];
        for (const tag of tagArr) {
          if (!seen.some(s => isSameTag(s, tag))) {
            seen.push(tag);
            deduped.push(tag);
          }
        }
        if (deduped.length !== tagArr.length) {
          newTagsStr = deduped.join(", ");
          changed = true;
        }
      }
      
      // 2. tag_data (JSON 배열) 중복 제거
      let newTagData = n.tag_data || "";
      if (n.tag_data) {
        try {
          const tdArr = JSON.parse(n.tag_data);
          if (Array.isArray(tdArr) && tdArr.length > 0) {
            const seenTd = [];
            const dedupedTd = [];
            for (const td of tdArr) {
              const tagName = td.tag || "";
              if (!seenTd.some(s => isSameTag(s, tagName))) {
                seenTd.push(tagName);
                dedupedTd.push(td);
              }
            }
            if (dedupedTd.length !== tdArr.length) {
              newTagData = JSON.stringify(dedupedTd);
              changed = true;
            }
          }
        } catch {}
      }
      
      // 3. major_genre (JSON 배열) 중복 제거
      let newMajor = n.major_genre || "";
      if (n.major_genre) {
        try {
          const arr = JSON.parse(n.major_genre);
          if (Array.isArray(arr) && arr.length > 0) {
            const seenM = [];
            const dedupedM = [];
            for (const g of arr) {
              if (!seenM.some(s => isSameTag(s, g))) {
                seenM.push(g);
                dedupedM.push(g);
              }
            }
            if (dedupedM.length !== arr.length) {
              newMajor = JSON.stringify(dedupedM);
              changed = true;
            }
          }
        } catch {}
      }
      
      // 4. sub_genre (JSON 배열) 중복 제거
      let newSub = n.sub_genre || "";
      if (n.sub_genre) {
        try {
          const arr = JSON.parse(n.sub_genre);
          if (Array.isArray(arr) && arr.length > 0) {
            const seenS = [];
            const dedupedS = [];
            for (const g of arr) {
              if (!seenS.some(s => isSameTag(s, g))) {
                seenS.push(g);
                dedupedS.push(g);
              }
            }
            if (dedupedS.length !== arr.length) {
              newSub = JSON.stringify(dedupedS);
              changed = true;
            }
          }
        } catch {}
      }
      
      if (changed) {
        updates.push({
          sql: "UPDATE novels SET tags=?, tag_data=?, major_genre=?, sub_genre=? WHERE id=?",
          params: [newTagsStr, newTagData, newMajor, newSub, n.id]
        });
      }
    }
    
    if (updates.length > 0) {
      // 청크 단위 배치 (50개씩)
      for (let i = 0; i < updates.length; i += 50) {
        await execBatch(updates.slice(i, i + 50));
      }
    }
    
    return { fixed: updates.length, total: novels.length };
  } catch (e) {
    console.warn("[deduplicateExistingNovelTags] 오류:", e);
    return { fixed: 0, total: 0, error: e.message };
  }
}

// 모든 기본 태그 중복 제거 검사
function getAllDefaultTagsDeduped() {
  const all = [...MAJOR_GENRES, ...SUB_GENRES];
  for (const categoryTags of Object.values(GENERAL_TAGS)) {
    all.push(...categoryTags);
  }
  return deduplicateTags(all);
}

// 모든 일반 태그 / 전체 기본 태그 → 런타임 let 블록으로 이동 (applyTagRegistry에서 재계산)

// JSON 배열 또는 단일 문자열을 배열로 파싱
function parseMajorSub(value) {
  if (!value) return [];
  try {
    const parsed = JSON.parse(value);
    return Array.isArray(parsed) ? parsed : [parsed];
  } catch {
    return value ? [value] : [];
  }
}

// 태그 사용 빈도 계산 함수
// 🔧 v3.5.11 성능: counts만 빠르게 계산 (O(n*m) — loadList 핫패스)
function countTagUsageFast(novels) {
  const counts = {};
  for (const n of novels) {
    const tags = (n.tags || "").split(",").map(t => t.trim()).filter(Boolean);
    const majorTags = parseMajorSub(n.major_genre);
    const subTags = parseMajorSub(n.sub_genre);
    const allTagsInNovel = [...new Set([...tags, ...majorTags, ...subTags])];
    for (const tag of allTagsInNovel) {
      counts[tag] = (counts[tag] || 0) + 1;
    }
  }
  return counts;
}

// 🔧 v3.5.11 성능: coOccurrences 지연 계산 (O(n*m²) — 태그 모달 열 때만)
function countTagCoOccurrences(novels) {
  const coOccurrences = {};
  for (const n of novels) {
    const tags = (n.tags || "").split(",").map(t => t.trim()).filter(Boolean);
    const majorTags = parseMajorSub(n.major_genre);
    const subTags = parseMajorSub(n.sub_genre);
    const allTagsInNovel = [...new Set([...tags, ...majorTags, ...subTags])];
    for (let i = 0; i < allTagsInNovel.length; i++) {
      const tagA = allTagsInNovel[i];
      if (!coOccurrences[tagA]) coOccurrences[tagA] = {};
      for (let j = 0; j < allTagsInNovel.length; j++) {
        if (i === j) continue;
        const tagB = allTagsInNovel[j];
        coOccurrences[tagA][tagB] = (coOccurrences[tagA][tagB] || 0) + 1;
      }
    }
  }
  return coOccurrences;
}

// 레거시 호환: 기존 호출부가 있을 경우 대비
function countTagUsage(novels) {
  const counts = countTagUsageFast(novels);
  const coOccurrences = countTagCoOccurrences(novels);
  return { counts, coOccurrences };
}

// 자주 쓰는 태그 정렬 (사용빈도순)
// 🆕 v3.5.9: 태그 카테고리 조회 (기본 + 커스텀 카테고리)
// 반환값: { category: "분위기/톤", isCustom: false } 또는 null (미분류)
function getTagCategory(tag, customTagCategories = {}) {
  // 기본 카테고리 검색
  for (const [category, tagList] of Object.entries(GENERAL_TAGS)) {
    if (tagList.some(t => t.toLowerCase() === tag.toLowerCase())) {
      return { category, isCustom: false };
    }
  }
  // 커스텀 카테고리 검색
  if (customTagCategories && typeof customTagCategories === "object") {
    for (const [catName, catTags] of Object.entries(customTagCategories)) {
      if (Array.isArray(catTags) && catTags.some(t => t.toLowerCase() === tag.toLowerCase())) {
        return { category: catName, isCustom: true };
      }
    }
  }
  return null;
}

function sortTagsByUsage(tags, usageCounts) {
  return [...tags].sort((a, b) => {
    const countA = usageCounts[a] || 0;
    const countB = usageCounts[b] || 0;
    if (countB !== countA) return countB - countA;
    return a.localeCompare(b);
  });
}

// 작품의 대장르/부장르 추출 (태그 기반 자동 감지)
function detectGenres(tagsStr) {
  const tags = (tagsStr || "").split(",").map(t => t.trim().toLowerCase()).filter(Boolean);
  
  let majorGenre = null;
  let subGenre = null;
  
  // 대장르 탐색 (🔧 정확한 매칭 우선 + includes 시 긴 장르명 우선 매칭)
  // 먼저 정확한 매칭 시도
  for (const tag of tags) {
    const exact = MAJOR_GENRES.find(g => g.toLowerCase() === tag);
    if (exact) { majorGenre = exact; break; }
  }
  // 정확한 매칭 없으면 포함 매칭 (긴 장르명부터 검사하여 "현대판타지" > "판타지" 우선)
  if (!majorGenre) {
    const sorted = [...MAJOR_GENRES].sort((a, b) => b.length - a.length);
    for (const tag of tags) {
      const found = sorted.find(g => tag.includes(g.toLowerCase()));
      if (found) { majorGenre = found; break; }
    }
  }

  // 부장르 탐색 (동일 로직)
  for (const tag of tags) {
    const exact = SUB_GENRES.find(g => g.toLowerCase() === tag);
    if (exact) { subGenre = exact; break; }
  }
  if (!subGenre) {
    const sorted = [...SUB_GENRES].sort((a, b) => b.length - a.length);
    for (const tag of tags) {
      const found = sorted.find(g => tag.includes(g.toLowerCase()));
      if (found) { subGenre = found; break; }
    }
  }
  
  return { majorGenre, subGenre };
}

