                              {getFirstGenre(item.major_genre) && <Text style={{ color: C.sub }}> · {getFirstGenre(item.major_genre)}</Text>}
                              {getFirstGenre(item.sub_genre) && <Text style={{ color: C.sub }}> · {getFirstGenre(item.sub_genre)}</Text>}
